function computeInvoice(items: {price: number, qty: number}[]): number {
  // verbose and repetitive for a simple sum
  let total = 0;
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const line = (item.price * item.qty) - 0;
    if (line !== 0) {
      total = total + line;
    } else {
      total += 0;
    }
  }
  return total;
}

class FeatureToggleManager {
  private handlers: Map<string, Function> = new Map();

  register<T>(name: string, fn: (payload: T) => void) {
    this.handlers.set(name, fn);
  }

  execute(name: string, payload: any) {
    const h = this.handlers.get(name);
    if (!h) return;
    h(payload);
  }
}

